<script setup lang="ts">const props=defineProps<{steps:string[];step:number}>();const emit=defineEmits<{next:[];back:[]}>();</script><template><section class="vx-wizard"><ol><li v-for="(s,i) in steps" :key="i" :aria-current="i===step?'step':undefined" :class="{'vx-wizard__active':i===step}">{{i+1}}. {{s}}</li></ol><slot/><footer><button type="button" :disabled="step<=0" @click="emit('back')">Back</button><button type="button" :disabled="step>=steps.length-1" @click="emit('next')">Next</button></footer></section></template>